import React, { useState } from 'react';
const getInvType = (id, types) => (types || []).find(t => t.id === id) || { id, label: id, color: '#8a8680', bg: '#f2f0ec' };
import SimpleEditor from './SimpleEditor';
import { parseEventDate } from '../data/timeline';

function CopyBtn({ text }) {
  const [copied, setCopied] = useState(false);
  return (
    <button onClick={() => { navigator.clipboard?.writeText(text); setCopied(true); setTimeout(() => setCopied(false), 1500); }}
      style={{ fontSize: 11, padding: '4px 12px', borderRadius: 6, border: '1px solid var(--paper-3)', color: copied ? 'var(--green)' : 'var(--ink-3)', background: 'var(--paper-card)', cursor: 'pointer' }}>
      {copied ? '✓ Copied' : 'Copy all'}
    </button>
  );
}

const STATUS_STYLES = {
  active: { color: '#2e7d5e', bg: '#e4f4ec', label: 'Active' },
  cold:   { color: '#7a6a52', bg: '#f0e8d8', label: 'Cold' },
  closed: { color: '#8a8680', bg: '#f2f0ec', label: 'Closed' },
};

export default function InvestigationCasePage({ inv, books, events, invTypes = [], onUpdate, onEdit, onBack, onViewTimeline }) {
  const invType = getInvType(inv.type, invTypes);
  const statusStyle = STATUS_STYLES[inv.status] || STATUS_STYLES.active;
  const linkedBooks = books.filter(b => (inv.bookIds || []).includes(b.id));

  // Timeline events that share any tag with this investigation
  const relatedEvents = events.filter(e =>
    e.tags?.some(tag => inv.tags?.includes(tag))
  );

  // Export markdown
  const exportText = [
    `# ${inv.title}`,
    `**Type:** ${invType.label} · **Status:** ${statusStyle.label}`,
    inv.dateRange ? `**Period:** ${inv.dateRange}` : '',
    '',
    inv.summary ? `## Opening question\n${inv.summary}` : '',
    '',
    inv.actors?.length ? `## Key actors\n${inv.actors.map(a => `- ${a}`).join('\n')}` : '',
    '',
    inv.causes?.length ? `## Causes / contributing factors\n${inv.causes.map(c => `- ${c}`).join('\n')}` : '',
    '',
    linkedBooks.length ? `## Book perspectives\n${linkedBooks.map(book => {
      const bn = inv.bookNotes?.find(n => n.bookId === book.id) || {};
      return `### ${book.title}\n${bn.quote ? `> "${bn.quote}"\n` : ''}${bn.note || ''}`;
    }).join('\n\n')}` : '',
    '',
    inv.analysis ? `## Analysis\n${inv.analysis.replace(/<[^>]*>/g, '')}` : '',
  ].filter(Boolean).join('\n');

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100%' }}>
      {/* Header */}
      <div style={{ padding: '12px 22px 10px', borderBottom: '1px solid var(--paper-3)', display: 'flex', alignItems: 'center', gap: 10, flexShrink: 0, background: 'var(--paper-2)' }}>
        <button onClick={onBack} style={{ fontSize: 13, color: 'var(--ink-3)', cursor: 'pointer', background: 'none', border: 'none' }}>← Investigation</button>
        <div style={{ width: 1, height: 16, background: 'var(--paper-3)' }} />
        <div style={{ width: 12, height: 12, borderRadius: 2, background: invType.color, flexShrink: 0 }} />
        <h1 style={{ fontSize: 16, fontWeight: 600, color: 'var(--ink)', flex: 1, lineHeight: 1.3 }}>{inv.title}</h1>
        <span style={{ fontSize: 10, padding: '2px 9px', borderRadius: 10, background: invType.bg + '55', color: invType.color, fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>{invType.label}</span>
        <span style={{ fontSize: 10, padding: '2px 9px', borderRadius: 10, background: statusStyle.bg + '55', color: statusStyle.color, fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>{statusStyle.label}</span>
        {inv.dateRange && <span style={{ fontSize: 11, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>{inv.dateRange}</span>}
        <CopyBtn text={exportText} />
        <button onClick={onEdit} style={{ fontSize: 12, padding: '5px 12px', borderRadius: 6, border: '1px solid var(--paper-3)', color: 'var(--ink-2)', background: 'transparent', cursor: 'pointer' }}>Edit</button>
      </div>

      {/* 3-column body */}
      <div style={{ flex: 1, overflow: 'hidden', display: 'grid', gridTemplateColumns: '1fr 260px 280px' }}>

        {/* LEFT — main content */}
        <div style={{ overflowY: 'auto', padding: '18px 20px', borderRight: '1px solid var(--paper-3)' }}>

          {/* Opening question */}
          {inv.summary && (
            <div style={{ background: invType.color + '11', border: `1px solid ${invType.color}33`, borderRadius: 10, padding: '14px 16px', marginBottom: 20 }}>
              <div style={{ fontSize: 10, fontWeight: 700, color: invType.color, fontFamily: 'var(--font-mono)', fontStyle: 'normal', textTransform: 'uppercase', letterSpacing: '0.07em', marginBottom: 6 }}>Opening question</div>
              <p style={{ fontSize: 14, color: 'var(--ink)', lineHeight: 1.7, fontStyle: 'italic' }}>{inv.summary}</p>
            </div>
          )}

          {/* Key actors */}
          {inv.actors?.length > 0 && (
            <div style={{ marginBottom: 20 }}>
              <div style={SL}>Key actors</div>
              <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6 }}>
                {inv.actors.map((a, i) => (
                  <span key={i} style={{ fontSize: 12, padding: '4px 12px', borderRadius: 20, background: 'var(--paper-card)', border: '1px solid var(--paper-3)', color: 'var(--ink-2)' }}>{a}</span>
                ))}
              </div>
            </div>
          )}

          {/* Causes */}
          {inv.causes?.length > 0 && (
            <div style={{ marginBottom: 20 }}>
              <div style={SL}>Causes / contributing factors</div>
              <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
                {inv.causes.map((c, i) => (
                  <div key={i} style={{ display: 'flex', alignItems: 'flex-start', gap: 8, fontSize: 13, color: 'var(--ink)', lineHeight: 1.5 }}>
                    <span style={{ color: invType.color, fontWeight: 700, flexShrink: 0, marginTop: 2 }}>·</span>
                    <span>{c}</span>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Analysis editor */}
          <div>
            <div style={SL}>Your analysis</div>
            <SimpleEditor
              value={inv.analysis || ''}
              onChange={val => onUpdate({ ...inv, analysis: val, updatedAt: new Date().toISOString() })}
              placeholder="Develop your analysis here — causes, patterns, what the sources agree and disagree on, your own conclusions…"
            />
          </div>

          {/* Tags */}
          {inv.tags?.length > 0 && (
            <div style={{ marginTop: 16 }}>
              <div style={SL}>Tags</div>
              <div style={{ display: 'flex', gap: 6, flexWrap: 'wrap' }}>
                {inv.tags.map(tag => (
                  <button key={tag} onClick={() => onViewTimeline?.(tag)}
                    style={{ fontSize: 11, padding: '3px 10px', borderRadius: 20, background: 'var(--paper-2)', color: 'var(--ink-3)', border: '1px solid var(--paper-3)', cursor: onViewTimeline ? 'pointer' : 'default' }}
                    onMouseEnter={e => { if (onViewTimeline) { e.currentTarget.style.background = 'var(--accent-light)'; e.currentTarget.style.color = 'var(--accent)'; }}}
                    onMouseLeave={e => { e.currentTarget.style.background = 'var(--paper-2)'; e.currentTarget.style.color = 'var(--ink-3)'; }}
                    title={onViewTimeline ? 'View related timeline events' : undefined}>
                    #{tag}{onViewTimeline ? ' →' : ''}
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>

        {/* MIDDLE — book perspectives */}
        <div style={{ overflowY: 'auto', padding: '18px 16px', borderRight: '1px solid var(--paper-3)', background: 'var(--paper-2)' }}>
          <div style={SL}>Book perspectives</div>
          {linkedBooks.length === 0 ? (
            <div style={{ fontSize: 12, color: 'var(--ink-4)', fontStyle: 'italic', lineHeight: 1.65, textAlign: 'center', padding: '20px 0' }}>
              No books linked yet.<br />Edit this case to add sources.
            </div>
          ) : linkedBooks.map(book => {
            const bn = inv.bookNotes?.find(n => n.bookId === book.id) || {};
            return (
              <div key={book.id} style={{ marginBottom: 18 }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: 6, marginBottom: 8, paddingBottom: 6, borderBottom: `2px solid ${book.color}33` }}>
                  <div style={{ width: 9, height: 9, borderRadius: '50%', background: book.color }} />
                  <div>
                    <div style={{ fontSize: 12, fontWeight: 500, color: book.color, fontStyle: 'italic' }}>{book.title}</div>
                    {book.author && <div style={{ fontSize: 10, color: 'var(--ink-4)' }}>{book.author}</div>}
                  </div>
                </div>
                {bn.quote ? (
                  <blockquote style={{ borderLeft: `2px solid ${book.color}55`, paddingLeft: 8, margin: '0 0 8px', fontSize: 12, color: 'var(--ink-2)', fontStyle: 'italic', lineHeight: 1.65 }}>
                    "{bn.quote}"
                  </blockquote>
                ) : null}
                {bn.note ? (
                  <p style={{ fontSize: 12, color: 'var(--ink)', lineHeight: 1.65 }}>{bn.note}</p>
                ) : (
                  !bn.quote && <p style={{ fontSize: 11, color: 'var(--ink-4)', fontStyle: 'italic' }}>No notes yet — edit to add.</p>
                )}
              </div>
            );
          })}
        </div>

        {/* RIGHT — related timeline events */}
        <div style={{ overflowY: 'auto', padding: '18px 16px' }}>
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 12 }}>
            <div style={SL}>Related timeline events</div>
            {relatedEvents.length > 0 && onViewTimeline && (
              <button onClick={() => onViewTimeline(inv.tags?.[0])}
                style={{ fontSize: 10, color: 'var(--accent)', background: 'none', border: 'none', cursor: 'pointer', fontFamily: 'var(--font-mono)', fontStyle: 'normal', textDecoration: 'underline' }}>
                View all →
              </button>
            )}
          </div>
          {relatedEvents.length === 0 ? (
            <div style={{ fontSize: 12, color: 'var(--ink-4)', fontStyle: 'italic', lineHeight: 1.65, textAlign: 'center', padding: '20px 0' }}>
              No matching timeline events yet.<br />Add tags to timeline events that match this investigation's tags.
            </div>
          ) : relatedEvents.map(ev => {
            const parsed = parseEventDate(ev.dateRaw);
            const evBooks = books.filter(b => (ev.bookIds || []).includes(b.id));
            return (
              <div key={ev.id}
                onClick={() => onViewTimeline?.(ev.tags?.[0] || inv.tags?.[0])}
                style={{ background: 'var(--paper-2)', border: '1px solid var(--paper-3)', borderRadius: 8, padding: '10px 12px', marginBottom: 8, cursor: onViewTimeline ? 'pointer' : 'default' }}
                onMouseEnter={e => { if (onViewTimeline) { e.currentTarget.style.background = 'var(--paper-card)'; e.currentTarget.style.borderColor = 'var(--accent-2)'; }}}
                onMouseLeave={e => { e.currentTarget.style.background = 'var(--paper-2)'; e.currentTarget.style.borderColor = 'var(--paper-3)'; }}>
                <div style={{ fontSize: 10, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal', marginBottom: 3 }}>{parsed.display || ev.dateRaw}</div>
                <div style={{ fontSize: 12, fontWeight: 500, color: 'var(--ink)', lineHeight: 1.35, marginBottom: 4 }}>{ev.title}</div>
                {evBooks.length > 0 && (
                  <div style={{ display: 'flex', gap: 4, flexWrap: 'wrap' }}>
                    {evBooks.map(b => <span key={b.id} style={{ display: 'flex', alignItems: 'center', gap: 3, fontSize: 10, color: b.color, fontStyle: 'italic' }}><div style={{ width: 5, height: 5, borderRadius: '50%', background: b.color }} />{b.title}</span>)}
                  </div>
                )}
                <div style={{ display: 'flex', gap: 4, marginTop: 4, flexWrap: 'wrap' }}>
                  {ev.tags?.filter(t => inv.tags?.includes(t)).map(t => (
                    <span key={t} style={{ fontSize: 9, padding: '1px 6px', borderRadius: 8, background: 'var(--accent-light)', color: 'var(--accent)', fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>#{t}</span>
                  ))}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

const SL = {
  fontSize: 10, fontWeight: 700, color: 'var(--ink-4)',
  letterSpacing: '0.08em', textTransform: 'uppercase',
  fontFamily: 'var(--font-mono)', fontStyle: 'normal',
  marginBottom: 10, paddingBottom: 6,
  borderBottom: '1px solid var(--paper-3)',
};
